					return [{"depth":2,"slug":"usps-marketing-mail-bulk-mail-what-it-is","text":"USPS Marketing Mail (Bulk Mail): What It Is"},{"depth":3,"slug":"marketing-mail-requirements","text":"Marketing Mail Requirements"},{"depth":2,"slug":"first-class-mail-when-its-worth-the-higher-rate","text":"First-Class Mail: When It’s Worth the Higher Rate"},{"depth":2,"slug":"the-postage-cost-comparison","text":"The Postage Cost Comparison"},{"depth":2,"slug":"when-first-class-is-the-right-choice","text":"When First-Class Is the Right Choice"},{"depth":2,"slug":"the-standard-recommendation","text":"The Standard Recommendation"},{"depth":2,"slug":"service-endorsements-getting-more-from-marketing-mail","text":"Service Endorsements: Getting More From Marketing Mail"},{"depth":2,"slug":"commingling-and-co-palletization-advanced-postage-optimization","text":"Commingling and Co-Palletization: Advanced Postage Optimization"},{"depth":2,"slug":"timing-your-mail-class-decision","text":"Timing Your Mail Class Decision"},{"depth":2,"slug":"nonprofit-marketing-mail-the-deepest-discount","text":"Nonprofit Marketing Mail: The Deepest Discount"}];
